import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Two actual damage roots reuse the admitted producer; existing action and inventory scopes stay authoritative. */
public final class SummonCombatMethods {
 static final String P="local/lito381/server/",PC=P+"ClientSession",PET=P+"BattleCompanion",H=P+"NativeSummonTerminalLifecycle",LIGHT=P+"NativeLightAction",NATURE=P+"NativeReturnNatureMaterialAction";
 static ClassNode read(JarFile j,String name)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(name+".class"))).accept(c,ClassReader.SKIP_DEBUG);return c;}
 static byte[] bytes(ClassNode c){var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static void patch(ClassNode c){
  if(c.name.equals(LIGHT)){
   if(c.methods.stream().anyMatch(m->m.name.equals("currentMaterialProducer")))throw new AssertionError("duplicate producer accessor");var m=new MethodNode(ACC_STATIC,"currentMaterialProducer","()L"+PC+";",null,null);var yes=new LabelNode();m.instructions.add(new FieldInsnNode(GETSTATIC,LIGHT,"current","Ljava/lang/ThreadLocal;"));m.instructions.add(new MethodInsnNode(INVOKEVIRTUAL,"java/lang/ThreadLocal","get","()Ljava/lang/Object;",false));m.instructions.add(new TypeInsnNode(CHECKCAST,LIGHT+"$Batch"));m.instructions.add(new InsnNode(DUP));m.instructions.add(new JumpInsnNode(IFNONNULL,yes));m.instructions.add(new InsnNode(POP));m.instructions.add(new InsnNode(ACONST_NULL));m.instructions.add(new InsnNode(ARETURN));m.instructions.add(yes);m.instructions.add(new FrameNode(F_SAME1,0,null,1,new Object[]{LIGHT+"$Batch"}));m.instructions.add(new FieldInsnNode(GETFIELD,LIGHT+"$Batch","pc","L"+PC+";"));m.instructions.add(new InsnNode(ARETURN));c.methods.add(m);return;
  }
  if(c.name.equals(NATURE)){
   var desc="(L"+PC+";L"+PC+";L"+PET+";L"+P+"NativeCompanionCallbacks$Stamp;)Ljava/lang/Object;";if(c.methods.stream().anyMatch(m->m.name.equals("ownerContext")&&m.desc.equals(desc)))throw new AssertionError("duplicate cross-producer owner context");var m=new MethodNode(ACC_STATIC,"ownerContext",desc,null,null);m.instructions.add(new TypeInsnNode(NEW,NATURE+"$Target"));m.instructions.add(new InsnNode(DUP));for(int i=0;i<4;i++)m.instructions.add(new VarInsnNode(ALOAD,i));m.instructions.add(new MethodInsnNode(INVOKESPECIAL,NATURE+"$Target","<init>",desc.replace(")Ljava/lang/Object;",")V"),false));m.instructions.add(new InsnNode(DUP));m.instructions.add(new InsnNode(ICONST_1));m.instructions.add(new FieldInsnNode(PUTFIELD,NATURE+"$Target","nativeSummonOwnerContext","Z"));m.instructions.add(new InsnNode(ARETURN));c.methods.add(m);return;
  }
  int roots=0;for(var m:c.methods)if(Set.of("applyClassicWorldMonsterCompanionDamageInternal","applyBattleCompanionFeedbackDamage").contains(m.name)){int damage=0,tail=0;for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode call){
   if(call.owner.equals(P+"NativeCombatAttacker")&&call.name.equals("companionDamage")){var in=new InsnList();in.add(new VarInsnNode(ALOAD,0));in.add(new InsnNode(DUP_X2));in.add(new InsnNode(POP));m.instructions.insertBefore(n,in);call.owner=H;call.name="combatDamage";call.desc="(L"+PC+";L"+PET+";I)L"+PET+"$Damage;";damage++;}
   else if(call.owner.equals(PET+"$Damage")&&call.name.equals("appliedDamage")&&tail==0){call.setOpcode(INVOKESTATIC);call.owner=H;call.name="legacyApplied";call.desc="(L"+PET+"$Damage;)I";tail++;}
  }if(damage!=1||tail!=1)throw new AssertionError("two exact death ports per root "+m.name);roots++;}if(roots!=2)throw new AssertionError("two actual damage roots");
 }
 public static void main(String[]a)throws Exception{try(var old=new JarFile(a[1])){for(var name:List.of(PC,LIGHT,NATURE)){var c=read(old,name);patch(c);var expected=bytes(c);if(a[0].equals("splice")){var p=Path.of(a[2]).resolve(name+".class");Files.createDirectories(p.getParent());Files.write(p,expected);}else try(var candidate=new JarFile(a[2])){if(!Arrays.equals(expected,bytes(read(candidate,name))))throw new AssertionError("exact regeneration differs "+name);}}}System.out.println("PASS four exact damage/tail ports and two existing-scope accessors; other methods and all fields retained");}
}
